#pragma once
#include <bearssl.h>

/* Built-in trust anchors of the Pi build: generated by tools/fetch_ca.py, or
 * user/lib/tls_trust_none.c (count 0) when no bundle was built. */
extern const br_x509_trust_anchor tls_trust_anchors[];
extern const size_t tls_trust_anchor_count;

#ifdef VANTAGE_SIM
/* Simulator and host tests only. The built-in anchors there are the virtual
 * network's CA (sim/platform/tls_peer.c); tls_set_trust_anchors replaces them
 * for later tls_open calls until it is called with NULL. The array must stay
 * valid while sessions use it. */
const br_x509_trust_anchor* tls_sim_trust_anchors(size_t* count);
void tls_set_trust_anchors(const br_x509_trust_anchor* anchors, size_t count);
#endif
